    async def send_message(
        self,
        instance_id: str,
        *,
        to: str,
        text: str,
        idempotency_key: str | None = None,
        time_limit: float | None = None,
    ) -> Sent[SendMessageResult]:
        """Send one text message.

        A 504 send_outcome_unknown means the message may or may not have been sent. After a 504,
        retry with the same key: the core sends the message at most once. After 429
        instance_queue_full or 409 send_in_progress, wait for `retry_after` seconds, then retry with
        the same key. A resend with a known key gets its answer also while the instance is not
        connected.

        Args:
            instance_id: The id of the instance, a UUID. Any other value gives 404 not_found.
            to: Not empty. At most 64 bytes. The core checks the format.
            text: At most 4096 characters, and not only spaces. The text is sent unchanged.
            idempotency_key: The key of this message: 1 to 255 printable ASCII characters, with no
                space. Make it with `new_idempotency_key` and store it before the call. Use a new
                key for each message. Use the same key only to repeat the same call. Calyx keeps a
                key for 24 hours. In that time, a second call with the same key does not send again.
                Without it, the SDK makes a new key. All callers of one instance share its keys.
            time_limit: The time limit of the call, in seconds. Without it, the `time_limit` of the
                SDK client applies, or 360 seconds when it has none.

        Returns:
            Sent[SendMessageResult]: `data` is the answer, and `idempotency_key` is the key that the
                call used. A message that WhatsApp accepted.

        Raises:
            CalyxError: The call failed. Read `retry` of the error to know what to do. Errors of the
                backend: 400 invalid_request, 401 unauthenticated, 404 not_found, 409
                instance_not_connected, 409 instance_not_ready, 409 idempotency_key_conflict, 409
                send_in_progress, 409 idempotency_key_outcome_unknown, 409 duplicate_message, 429
                instance_queue_full, 502 core_rejected_token, 504 send_outcome_unknown. When `retry`
                is `RetryAdvice.RETRY_NOW`, call again with the same arguments and the
                `idempotency_key` of the error. When it is `RetryAdvice.RETRY_LATER`, do the same,
                but first wait for `retry_after` seconds or more. If it is 0, choose the time to
                wait. Calyx forgets a key after 24 hours, so do not call again after that time. A
                cancelled call raises no `CalyxError`, and a key that the SDK made is lost. A
                cancelled call with no stored key cannot be repeated safely.
        """
        return await self._send(
            SEND_MESSAGE,
            path_id=instance_id,
            arguments={"to": to, "text": text},
            idempotency_key=idempotency_key,
            time_limit=time_limit,
        )

    @overload
    async def create_bulk_job(
        self,
        instance_id: str,
        *,
        recipients: Sequence[str],
        text: str,
        pacing: BulkPacingInput | None = None,
        idempotency_key: str | None = None,
        time_limit: float | None = None,
    ) -> Sent[BulkJob]:
        """Start a bulk job: one text for many recipients, or custom messages.

        Send either recipients with text, or messages. Anti-spam: with text, each recipient appears
        once; with messages, a recipient gets at most 2 messages. Pacing units: delay and
        pause_duration are in milliseconds, pause_every counts messages. The backend adds no pacing
        and never lowers it. A 504 bulk_outcome_unknown means that the job may run in the core
        without a backend record. Retry with the same key: the retry gives the job and stores it.
        Without this retry, the job cannot be read or cancelled through the backend, and the core's
        bulk.finished webhook still reports it. Do not start it again with a new key.

        Args:
            instance_id: The id of the instance, a UUID. Any other value gives 404 not_found.
            messages: 1 to 5000 messages. Use it without recipients and text. More than 5000 gives
                413 too_many_messages.
            pacing: The pacing of the job. The core keeps its minimums. Optional. An explicit None
                is the same as an absent field.
            recipients: 1 to 5000 recipients. Use it with text, and without messages. More than 5000
                gives 413 too_many_messages.
            text: At most 4096 characters, and not only spaces. The text is sent unchanged.
            idempotency_key: The key of this job: 1 to 255 printable ASCII characters, with no
                space. Make it with `new_idempotency_key` and store it before the call. Use a new
                key for each job. Use the same key only to repeat the same call. Calyx keeps a key
                for 24 hours. In that time, a second call with the same key does not send again.
                Without it, the SDK makes a new key. All callers of one instance share its keys.
            time_limit: The time limit of the call, in seconds. Without it, the `time_limit` of the
                SDK client applies, or 150 seconds when it has none.

        Returns:
            Sent[BulkJob]: `data` is the answer, and `idempotency_key` is the key that the call
                used. A bulk job: many messages that one instance sends in the background, with
                delays between them.

        Raises:
            CalyxError: The call failed. Read `retry` of the error to know what to do. Errors of the
                backend: 400 invalid_request (also the core's pacing refusal), 401 unauthenticated,
                404 not_found, 409 instance_not_connected, 409 instance_not_ready, 409
                idempotency_key_conflict, 413 too_many_messages, 502 core_rejected_token, 504
                bulk_outcome_unknown. When `retry` is `RetryAdvice.RETRY_NOW`, call again with the
                same arguments and the `idempotency_key` of the error. When it is
                `RetryAdvice.RETRY_LATER`, do the same, but first wait for `retry_after` seconds or
                more. If it is 0, choose the time to wait. Calyx forgets a key after 24 hours, so do
                not call again after that time. A cancelled call raises no `CalyxError`, and a key
                that the SDK made is lost. A cancelled call with no stored key cannot be repeated
                safely.
        """

